import HTML from "./html/card.html";
export default class CardElement extends HTMLElement {
    connectedCallback() {
        this.innerHTML = HTML;
    }
    async setTitle(title) {
        await this.connectedCallback();
        const titleElement = this.querySelector(".card-title");
        titleElement.textContent = title;
    }
    async setText(text) {
        await this.connectedCallback();
        const textElement = this.querySelector(".card-text");
        textElement.textContent = text;
    }
}
customElements.define("app-card", CardElement);
