import HTML from "./html/login.html";
import LoginController from "./controllers/login_controller";
export default class LoginElement extends HTMLFormElement {
    connectedCallback() {
        this.innerHTML = HTML;
        this.controller = new LoginController(this);
        this.connectButton = this.querySelector("#connect-button");
        this.registerButton = this.querySelector("#register-button");
        this.connectButton.onclick = (event) => this.controller.onLoginClick(event);
        this.registerButton.onclick = (event) => this.controller.onRegisterClick(event);
    }
    updateUser(user) {
        return;
    }
}
customElements.define("app-login", LoginElement, { extends: "form" });
